export const SIDE_CONTENT=[
 ['marchMeadow','Nest keeper Alice de Beaumont','010','361','Sheltered pine nests keep young Abyssals warm. Pricklet is shy; I raised this one away from the road.',{bread:4,poultices:2},'hedgerow'],
 ['burrowHollow','Burrow surveyor Henry FitzWalter','014','335','Bilbit usually hides under the dunes. A Mottlet could help me map the tunnels without disturbing the nests.',{armedEscorts:1,smoke:2},'burrows'],
 ['glassSluice','Mineral keeper Agnes Giffard','016','301','Prismip reflects the cold mineral pools. Tokenail can carry my instruments through the narrow sluice.',{held:'HELD_TYPE_SIGIL_ICE'},'glass'],
 ['emberQuarry','Forge apprentice Musa al-Haddad','141','315','Anvilip rests beside the abandoned forge. I need a Pilgrimp to carry messages to the road crew.',{held:'HELD_TYPE_SIGIL_FIRE'},'embers'],
 ['stormBluffs','Cliff watcher Umar ibn Ibrahim','099','299','Flurrit rides the icy updrafts. Whisbat could scout the cliff caves after dark.',{armedEscorts:1,emergencyEvacs:1},'storm'],
 ['orchardCanopy','Orchard keeper Hasan ibn Ali','141','337','Lanterpip lights the old orchard at night. A Pilgrimp could carry fruit back to the hospice.',{bread:5,poultices:3},'orchard'],
 ['reedSanctuary','Reed warden Asma bint Musa','152','313','Billock waits motionless among the reeds. Acremink could help me track polluted streams.',{held:'HELD_TYPE_SIGIL_WATER'},'reeds'],
 ['coralGrotto','Tide scholar Ismail ibn Hasan','051','307','Palmote shelters in the coral cracks. A Rillip could guide me through the fresh water above.',{smoke:3,emergencyEvacs:1},'coral'],
 ['moonlitDepths','Dream researcher Ali ibn Umar','110','343','Notionip followed me here from the orchard. Styxlet could guide my boat through the dark pools.',{held:'HELD_TYPE_SIGIL_GHOST'},'moon'],
 ['relicCrags','Shellstone scholar Amina bint Ibrahim','141','351','Onyxip hides beneath the black shelves after dusk. Pilgrimp could carry our shellstone samples.',{trainingTonics:1},'relic']
].map(([room,name,wanted,offered,lore,reward,theme],i)=>({room,name,wanted,offered,lore,reward,theme,index:i,id:'explore-'+room}));
export const CAVE_FLOORS=[
 {room:'waranCave1',name:'Veilroot Bastion · Gatehouse',min:12,max:16,theme:'fort-1',species:['025','038','351','329'],trainer:['025','351'],levels:[16,16],npc:'Relic hunter Freya',npcText:'I came for the old garrison seals. The salt has eaten most of the iron, but the stone plaques still read clearly. I learned field medicine before I learned to read these seals. Bring your partners here when they need healing; I keep clean bandages and warm water ready. Bring me rubbings from the first three floors and I will share my supplies.',trainerText:'The gatehouse stores have already been picked clean. I am taking a rope down to the barracks. Show me your partners can handle the descent before you use it.',reward:{bread:3,poultices:2},lore:'The oldest carving shows three Abyssals beneath a peach tree: Feirong, Guanrong and Liubeirow. Their Peach Orchard oath binds strength, loyalty and mercy. Beneath them, Waranwei follows their roots. It hunts all three tirelessly; no border, winter or army has ever ended the pursuit.'},
 {room:'waranCave2',name:'Veilroot Bastion · Drowned Barracks',min:22,max:28,theme:'fort-2',species:['301','303','325','351'],trainer:['301','325'],levels:[28,28],npc:'Salvager Robert de Mortimer',npcText:'I am hunting a bronze pay chest under the bunks. Something pale and leafy slipped between the pillars earlier. Never seen one like it. It left a sweet smell over all this brine.',trainerText:'Old coins settle under the collapsed bunks. I have a claim on this stair, but beat me and you can search the armoury first.',reward:{heartyFood:2,smoke:1},lore:'Feirong roars to draw the hunter away from the wounded. Guanrong stands between its fangs and those seeking shelter. Liubeirow heals the survivors and coaxes poisoned orchards back to life. Together they can drive Waranwei back. Separated, each becomes its quarry. The peach blossom scent left by their shared power betrays their trail. Old hunters say their oath-fed sap renews Waranwei’s venom; ordinary prey never satisfies it for long.'},
 {room:'waranCave3',name:'Veilroot Bastion · Tidal Armoury',min:34,max:40,theme:'fort-3',species:['032','152','317','352'],trainer:['032','352'],levels:[40,40],npc:'Treasure hunter Margaret de Mowbray',npcText:'A sealed weapon rack could pay for this whole expedition. While I was prying it open, I heard claws scraping the stair below. Whatever made that noise was much heavier than a person.',trainerText:'Salt water ruined the blades, but the fittings are silver. My partners help haul them up. Something with a long tail scraped past the racks earlier; no idea what it was. Let us see who earns first pick downstairs.',reward:{poultices:3,armedEscorts:1},lore:'The city of Kesh fell in a single night after sheltering Liubeirow. Waranwei poisoned its wells, shattered its gates and tore through whole districts searching for its meal. A second ruin records the same hunt for Guanrong. These were not battles for territory: the cities were obstacles between a predator and the three it craved.'},
 {room:'waranCave4',name:'Veilroot Bastion · Sunken Reliquary',min:46,max:52,theme:'fort-4',species:['304','326','330','352'],trainer:['326','330','352'],levels:[50,51,52],npc:'Relic diver Henry Giffard',npcText:'I am looking for a reliquary small enough to carry. Saw a long, low creature with violet scales and a dripping jaw go downstairs. It smashed a door without slowing down. I do not know what it was; I stayed hidden.',trainerText:'The reliquary has not been searched properly. I glimpsed a violet, heavy-jawed creature on the stairs. Never seen anything like it. Prove you can keep your partners safe before I lend you the last descent rope.',reward:{held:"HELD_TYPE_SIGIL_WATER",heartyFood:2},lore:'Waranwei learned to split the oathbound three. It feints at refugees to draw Guanrong away, answers Feirong’s roar from another valley and follows the healing sap Liubeirow leaves behind. Both armies have tried to lure it towards enemy cities with stolen peach branches. Nobody has ever controlled what happens after it arrives.'},
 {room:'waranCave5',name:'Veilroot Bastion · Lowest Cistern',min:56,max:60,theme:'fort-5',species:['032','304','326','352'],trainer:['032','326','352'],levels:[58,59,60],npc:'Salvager John FitzHugh',npcText:'I came for the offering boxes, but I am leaving them. A wounded, leafy Abyssal ran towards the old fountain. A huge scaled thing followed it, tasting the air. Stay near the stairs. I only want to get my salvage out alive.',trainerText:'I was after the cistern offerings. Now I just want enough supplies to climb out. A quick challenge: the winner gets first pick of my salvage route.',reward:{trainingTonics:2,emergencyEvacs:1},lore:'The cistern tablet records the last refuge: Liubeirow entered Veilroot to cleanse water poisoned by Waranwei’s hunt. Feirong drew the hunter across the ridge while Guanrong sheltered the fleeing townsfolk. But the peach scent led Waranwei back. Let the healer pass unhindered through these halls; bar its escape, and the hunter will break this bastion as it broke Kesh.'}
].map((f,i)=>({...f,species:FORT_POOLS[i],trainer:[['025','351','021','255','349','364'],['301','325','255','022','321','364'],['032','352','022','268','321','364'],['326','330','352','257','377','380'],['032','326','352','269','350','384']][i],levels:[[14,14,15,15,16,16],[25,26,26,27,28,28],[37,38,38,39,40,40],[49,50,50,51,52,52],[57,58,58,59,60,60]][i],index:i,trainerId:'TRN-CAVE-'+(i+1),trainerName:['Treasure hunter Hugh de Montfort', 'Relic hunter Agnes de Vesci', 'Treasure hunter Walter FitzHenry', 'Relic hunter Alice de Mortimer', 'Treasure hunter Richard de Beaumont'][i]}));

const salvageVoices=[
 ['The rope is yours. Salt has ruined the old stores; the villages pay well for any fittings that still hold. Leave the stair clear for the next crew.','My last buyer wanted gate hinges for a village that has changed hands four times. He asked me whether I could find a lock neither army could open.'],
 ['You earned the next descent. The pay chest would settle my crew’s winter debts, if it is still here.','Both armies stamped these coins in their turn. A baker will still take them if you scrape the salt off.'],
 ['Fairly won. You can search below. The silver fittings are worth more than these blades ever were.','The armoury supplied the coast before the sea broke in. Now village smiths melt its buckles into tools. I would rather sell them those than swords.'],
 ['Take the rope. If the creature comes back up, leave the relics and move. There is no treasure worth closing someone’s escape.','People paid offerings here for safe journeys. I keep wondering what they would make of us carrying the boxes out past all these flooded beds.'],
 ['You have earned your way through. I am taking my partners back to the stairs while we still have the strength to climb.','The officers used to promise this bastion could never fall. The sea did not need an army. I will remember that next time someone promises me a safe wall.']
];
for(const f of CAVE_FLOORS)[f.trainerAfter,f.trainerRepeat]=salvageVoices[f.index];
